Copy the workbook, read cached values from `Data` and `Lookup`, then match each Lookup year to the year row in `Data` and take the corresponding Row 14 value from that year’s column block. Unmatched years are left empty. Write the computed plain values into `Lookup!B2:B12`.

```python
import shutil
import openpyxl

shutil.copy(INIT, OUT)

vals = openpyxl.load_workbook(INIT, data_only=True)
wb = openpyxl.load_workbook(OUT)

data = vals["Data"]
lookup_vals = vals["Lookup"]
lookup = wb["Lookup"]

def norm_key(v):
    if v is None:
        return None
    if isinstance(v, bool):
        return str(v)
    if isinstance(v, (int, float)):
        f = float(v)
        return int(f) if f.is_integer() else f
    s = str(v).strip()
    if not s:
        return None
    try:
        f = float(s)
        return int(f) if f.is_integer() else f
    except ValueError:
        return s

def as_number(v):
    if v is None or isinstance(v, bool):
        return None
    if isinstance(v, (int, float)):
        f = float(v)
        return int(f) if f.is_integer() else f
    if isinstance(v, str):
        s = v.strip()
        if not s:
            return None
        try:
            f = float(s)
            return int(f) if f.is_integer() else f
        except ValueError:
            return None
    return None

YEAR_ROW = 4
VALUE_ROW = 14
max_col = data.max_column

year_cols = []
for col in range(1, max_col + 1):
    v = data.cell(row=YEAR_ROW, column=col).value
    key = norm_key(v)
    if key is not None:
        year_cols.append((col, key))
year_cols.sort(key=lambda x: x[0])

def find_value(year):
    match_col = None

    for col, key in year_cols:
        if key == year:
            match_col = col
            break

    if match_col is None:
        for col, key in year_cols:
            if isinstance(year, (int, float)) and isinstance(key, (int, float)):
                if abs(float(year) - float(key)) < 1e-9:
                    match_col = col
                    break

    if match_col is None:
        return None

    v = as_number(data.cell(row=VALUE_ROW, column=match_col).value)
    if v is not None:
        return v

    next_col = None
    for col, key in year_cols:
        if col > match_col:
            next_col = col
            break

    end = next_col if next_col is not None else max_col + 1
    for col in range(match_col, end):
        v = as_number(data.cell(row=VALUE_ROW, column=col).value)
        if v is not None:
            return v

    return None

years = []
for r in range(2, 13):
    years.append(norm_key(lookup_vals.cell(row=r, column=1).value))

for i in range(1, len(years)):
    if years[i] is None and isinstance(years[i - 1], int):
        years[i] = years[i - 1] + 1

results = []
for r, year in zip(range(2, 13), years):
    val = find_value(year)
    lookup.cell(row=r, column=2).value = val
    results.append((r, year, val))

wb.save(OUT)

print("year_cols:", year_cols)
print("results:", results)
```

